import { afterEach, expect, it } from 'vitest';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { nativeVerificationFixture } from '../helpers/native-verification-fixture.js';
import { ensureCliBuilt } from '../helpers/ensure-cli-built.js';
import { execFileSync } from 'node:child_process';
import { fixtureAcceptanceReview } from '../helpers/native-builder-acceptance-review.js';

const roots: string[] = [];
afterEach(async () => {
  for (const root of roots.splice(0)) await fs.rm(root, { recursive: true, force: true });
});

it('submits the typed receipt template through the public CLI without rebuilding identity fields', async () => {
  await ensureCliBuilt(path.resolve('.'));
  const binary = path.resolve('bin/comet.js');
  const originalTask = 'Produce the expected value without changing the public interface.';
  const fixture = await nativeVerificationFixture((root) => roots.push(root), binary, originalTask);
  const pending = await fixture.invoke('next', 'verification-test');
  const requestFile = path.join(path.dirname(fixture.root), 'opaque-result.json');
  const dispatch = async (request: unknown) => {
    await fs.writeFile(requestFile, JSON.stringify(request));
    return JSON.parse(
      execFileSync(
        process.execPath,
        [
          binary,
          'runtime',
          'dispatch',
          '--application',
          'native',
          '--project-root',
          fixture.root,
          '--request',
          requestFile,
          '--json',
        ],
        { encoding: 'utf8', windowsHide: true, timeout: 30000 },
      ),
    );
  };
  const claimed = await dispatch({
    ...pending.data.pendingAction.claimRequest,
    sessionId: 'public-builder',
  });
  const request = claimed.data.resultRequest;
  expect(claimed.data.originalRequest).toEqual({ source: 'run.input.task', text: originalTask });
  expect(request.result.output).toMatchObject({
    verificationChecks: [expect.any(Object)],
    acceptanceReview: [{ id: 'A1' }],
  });
  expect(claimed.data.checkRequestTemplate).toMatchObject({
    executable: expect.any(String),
    argv: expect.any(Array),
  });
  await fs.writeFile(path.join(fixture.root, 'value.txt'), 'expected\n');
  request.result.output = {
    ...request.result.output,
    summary: 'Implemented the expected value.',
    acceptanceReview: fixtureAcceptanceReview(['A1']),
    checks: [],
    knownLimits: [],
    verificationChecks: [
      {
        id: 'read-value',
        name: 'Read the final value',
        executable: process.execPath,
        argv: ['-e', "process.stdout.write(require('node:fs').readFileSync('value.txt','utf8'))"],
        cwdRef: '.',
        timeoutMs: 10000,
        repeatable: true,
      },
    ],
  };
  await dispatch(request);
  const accepted = await fixture.inspect();
  expect(accepted.actions.at(-1)).toMatchObject({ stepId: 'verify.checks', status: 'pending' });
  await dispatch(request);
  expect(await fixture.inspect()).toEqual(accepted);
  const review = await fixture.invoke('next', 'verification-test');
  const reviewer = await dispatch({
    ...review.data.pendingAction.claimRequest,
    sessionId: 'public-reviewer',
  });
  expect(reviewer.data.resultRequest.result.output.response.result.requestReview).toMatchObject({
    result: '<aligned|conflict|blocked>',
  });
  await dispatch(reviewer.data.refreshChecksResultRequest);
  await fixture.invoke('next', 'verification-test');
  const refreshed = await fixture.inspect();
  expect(refreshed.actions.at(-1)).toMatchObject({ stepId: 'verify.verifier', status: 'pending' });
  expect(
    refreshed.actions.filter((action) => action.stepId === 'verify.requested-checks'),
  ).toHaveLength(1);
  const continuation = await fixture.invoke('next', 'verification-test');
  const resumed = await dispatch({
    ...continuation.data.pendingAction.claimRequest,
    sessionId: 'public-reviewer',
  });
  const finalRequest = resumed.data.resultRequest;
  finalRequest.result.output.response.result = {
    ...finalRequest.result.output.response.result,
    verdict: 'pass',
    acceptance: [
      { id: 'A1', result: 'passed', reason: 'The final value meets the original requirement.' },
    ],
    risks: [],
    summary: 'The original request, Spec and current value agree.',
    requestReview: {
      result: 'aligned',
      reason: 'The expected value is implemented and the public interface remains unchanged.',
    },
  };
  await dispatch(finalRequest);
  expect((await fixture.inspect()).state).toMatchObject({ verification_result: 'pass' });
}, 90000);

import { afterEach, expect, it } from 'vitest';
import { promises as fs } from 'node:fs';
import { nativeVerificationFixture } from '../../helpers/native-verification-fixture.js';
import { projectNativeSdkContinuation } from '../../../domains/comet-native/native-sdk-continuation.js';
import type { WorkflowRun, RuntimeValue } from '../../../domains/engine/runtime.js';
import type { NativePortableState } from '../../../domains/comet-native/native-portable-types.js';
const roots: string[] = [];
afterEach(async () => {
  for (const root of roots.splice(0)) await fs.rm(root, { recursive: true, force: true });
});

function final(run: WorkflowRun, sessionId: string, verdict = 'pass'): RuntimeValue {
  const state = run.state as {
    builder_handoff: { candidate_id: string };
    loop: { iteration: number; attempt: number };
  };
  return {
    candidateId: state.builder_handoff.candidate_id,
    verifierExecutionRef: sessionId,
    response: {
      kind: 'final-result',
      result: {
        iteration: state.loop.iteration,
        attempt: state.loop.attempt,
        verdict,
        acceptance:
          verdict === 'pass'
            ? [{ id: 'A1', result: 'passed', reason: 'Read the final value.' }]
            : [{ id: 'A1', result: 'failed', reason: 'The value is wrong.' }],
        risks: [],
        summary: 'Read the final value and caller.',
      },
    },
  };
}

it('binds the original task and rejects a passing review that omits or contradicts it', async () => {
  const task = 'Recover the original operation after a disconnect; keep the public interface.';
  const fixture = await nativeVerificationFixture((root) => roots.push(root), undefined, task);
  const run = await fixture.candidate('expected\n');
  expect(run.input).toMatchObject({ task });
  const dispatchView = await projectNativeSdkContinuation({
    run,
    state: run.state as unknown as NativePortableState,
    projectRoot: fixture.root,
  });
  const dispatched = dispatchView.pendingActions.find(
    (entry) => entry.stepId === 'verify.verifier',
  );
  expect(dispatched?.sessionRequirements).toMatchObject({ independent: true, readOnly: true });
  const review = (current: typeof run) => {
    const output = final(current, 'reviewer');
    return output;
  };
  await expect(fixture.submit(review(run), 'reviewer')).rejects.toThrow(/requestReview/);
  const contradicted = review(await fixture.inspect());
  (contradicted.response.result as Record<string, unknown>).requestReview = {
    result: 'conflict',
    reason: 'The Spec excludes recovery required by the original task.',
  };
  await expect(fixture.submit(contradicted, 'reviewer')).rejects.toThrow(/requestReview/);
  (contradicted.response.result as Record<string, unknown>).requestReview = {
    result: 'blocked',
    reason: 'The original requirement remains unclear.',
  };
  await expect(fixture.submit(contradicted, 'reviewer')).rejects.toThrow(/requestReview/);
  const aligned = review(await fixture.inspect());
  (aligned.response.result as Record<string, unknown>).requestReview = {
    result: 'aligned',
    reason: 'Compared the original task, authorized scope and actual implementation.',
  };
  await fixture.submit(aligned, 'reviewer');
  expect((await fixture.inspect()).state).toMatchObject({ verification_result: 'pass' });
});

import { execFileSync, spawnSync } from 'node:child_process';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { runNativeCli } from '../../domains/comet-native/native-cli.js';
import { loadOwnedNativeSdkRuntime } from '../../domains/comet-native/native-runtime-ownership.js';
import { createNativePortableState } from '../../domains/comet-native/native-portable-state.js';
import { runtimeDispatchCommand } from '../../app/commands/runtime.js';
import {
  defaultProjectConfig,
  writeProjectConfig,
} from '../../domains/comet-native/native-config.js';
import { fixtureAcceptanceReview } from './native-builder-acceptance-review.js';
import type { RuntimeValue } from '../../domains/engine/runtime.js';

export async function nativeVerificationFixture(
  onRoot?: (root: string) => void,
  cliPath?: string,
  task?: string,
) {
  const temporary = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-verification-'));
  onRoot?.(temporary);
  const root = path.join(temporary, 'project');
  await fs.mkdir(root);
  let requestIndex = 0;
  const cli = (args: string[]) => {
    const execution = spawnSync(process.execPath, [cliPath!, ...args], {
      encoding: 'utf8',
      windowsHide: true,
    });
    if (execution.status !== 0) throw new Error(execution.stdout + execution.stderr);
    return JSON.parse(execution.stdout.slice(execution.stdout.indexOf('{')));
  };
  const dispatch = async (request: Record<string, unknown>) => {
    const file = path.join(temporary, `request-${++requestIndex}.json`);
    await fs.writeFile(file, JSON.stringify(request));
    const result = cli([
      'runtime',
      'dispatch',
      '--application',
      'native',
      '--project-root',
      root,
      '--request',
      file,
      '--json',
    ]);
    if (result.status !== 'succeeded') throw new Error(JSON.stringify(result));
    return result.data;
  };
  const load = async () => {
    const owned = await loadOwnedNativeSdkRuntime(root, 'verification-test');
    return { ...owned, run: await owned.runtime.inspect('verification-test') };
  };
  const git = (...args: string[]) =>
    execFileSync('git', ['-C', root, ...args], { windowsHide: true, stdio: 'pipe' });
  git('init');
  await fs.writeFile(path.join(root, 'value.txt'), 'initial\n');
  git('add', 'value.txt');
  git(
    '-c',
    'user.name=Fixture',
    '-c',
    'user.email=fixture@example.invalid',
    'commit',
    '-m',
    'initial',
  );
  const config = defaultProjectConfig('docs', 'zh-CN');
  await writeProjectConfig(root, config);
  const invoke = async (...args: string[]) => {
    if (cliPath) {
      const result = cli(['native', ...args, '--project-root', root, '--json']) as Awaited<
        ReturnType<typeof runNativeCli>
      >;
      if (result.exitCode !== 0) throw new Error(JSON.stringify(result));
      return result;
    }
    const result = await runNativeCli([...args, '--project-root', root, '--json']);
    if (result.exitCode !== 0) throw new Error(JSON.stringify(result));
    return result;
  };
  const change = path.join(root, 'docs/comet/changes/verification-test');
  await fs.mkdir(change, { recursive: true });
  // Exercise the legacy typed receipt and mandatory independent review contract.
  const initial = {
    operation: 'start',
    runId: 'verification-test',
    workflow: { id: 'comet-native', version: '1' },
    input: { name: 'verification-test', artifactRootRef: 'docs', ...(task ? { task } : {}) },
    initialState: createNativePortableState({
      name: 'verification-test',
      language: 'zh-CN',
      nextAction: 'prepare-shape-confirmation',
    }),
  };
  if (cliPath) await dispatch(initial);
  else {
    const request = path.join(temporary, 'start.json');
    await fs.writeFile(request, JSON.stringify(initial));
    const started = await runtimeDispatchCommand({
      projectRoot: root,
      application: 'native',
      request,
    });
    if (started.exitCode !== 0) throw new Error(JSON.stringify(started));
  }
  await fs.writeFile(
    path.join(change, 'brief.md'),
    '# Outcome\nDeliver the expected value.\n# Scope\nChange the value.\n## Directory structure\n### Modified\n- value.txt — expected value.\n# Non-goals\nNo unrelated changes.\n# Acceptance examples\n- The value is expected.\n',
  );
  await fs.mkdir(path.join(change, 'specs/value'), { recursive: true });
  await fs.writeFile(
    path.join(change, 'specs/value/spec.md'),
    '# Value\nThe final value is expected.\n',
  );
  await invoke('next', 'verification-test');
  let owned = await load();
  const state = owned.run.state as { state_version: number };
  await invoke(
    'next',
    'verification-test',
    '--confirmed',
    '--summary',
    'Approve fixture shape',
    '--expected-state-version',
    String(state.state_version),
    '--expected-action',
    'confirm-shape',
  );
  const submit = async (output: RuntimeValue, sessionId: string) => {
    if (cliPath) {
      const run = await dispatch({ operation: 'inspect', runId: 'verification-test' });
      const action = run.actions.at(-1)!;
      const claimToken =
        action.claim?.sessionId === sessionId ? action.claim.token : crypto.randomUUID();
      if (action.claim?.sessionId !== sessionId)
        await dispatch({
          operation: 'claim',
          runId: run.runId,
          actionId: action.id,
          attempt: action.attempt,
          inputHash: action.inputHash,
          executorId: 'native-host',
          sessionId,
          claimToken,
        });
      await dispatch({
        operation: 'record-outcome',
        runId: run.runId,
        outcome: {
          actionId: action.id,
          attempt: action.attempt,
          inputHash: action.inputHash,
          claimToken,
          outcomeId: crypto.randomUUID(),
          status: 'succeeded',
          output,
        },
      });
      return dispatch({ operation: 'inspect', runId: run.runId });
    }
    owned = await load();
    const action = owned.run.actions.at(-1)!;
    const context = { projectRoot: root, requestId: crypto.randomUUID() };
    const claimed =
      action.claim?.sessionId === sessionId
        ? owned.run
        : await owned.runtime.claim({
            runId: owned.run.runId,
            actionId: action.id,
            attempt: action.attempt,
            inputHash: action.inputHash,
            executorId: 'native-host',
            sessionId,
            claimToken: crypto.randomUUID(),
            context,
          });
    return owned.runtime.recordOutcome({
      runId: owned.run.runId,
      outcome: {
        actionId: action.id,
        attempt: action.attempt,
        inputHash: action.inputHash,
        claimToken: claimed.actions.at(-1)!.claim!.token,
        outcomeId: crypto.randomUUID(),
        status: 'succeeded',
        output,
      },
      context,
    });
  };
  const candidate = async (
    value: string,
    sessionId = 'builder',
    verificationChecks: RuntimeValue[] = [],
  ) => {
    await fs.writeFile(path.join(root, 'value.txt'), value);
    await submit(
      {
        summary: 'Implement expected value',
        acceptanceReview: fixtureAcceptanceReview(['A1']) as unknown as RuntimeValue,
        checks: [],
        knownLimits: [],
        verificationChecks,
      },
      sessionId,
    );
    await invoke('next', 'verification-test');
    return cliPath
      ? dispatch({ operation: 'inspect', runId: 'verification-test' })
      : (await load()).run;
  };
  return {
    root,
    change,
    invoke,
    submit,
    candidate,
    inspect: async () =>
      cliPath ? dispatch({ operation: 'inspect', runId: 'verification-test' }) : (await load()).run,
  };
}

import { spawn, spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeAll, expect, it } from 'vitest';
import { ensureCliBuilt } from '../helpers/ensure-cli-built.js';
import { prepareClassicLegacyProject } from '../helpers/classic-project.js';

const repository = path.resolve('.');
const roots: string[] = [];
beforeAll(() => ensureCliBuilt(repository), 120_000);
afterEach(async () => {
  for (const root of roots.splice(0)) {
    const resolved = await fs.realpath(root);
    if (
      path.dirname(resolved) !== (await fs.realpath(os.tmpdir())) ||
      !path.basename(resolved).startsWith('comet-cli-handoffs-')
    )
      throw new Error('Unexpected test cleanup target');
    await fs.rm(resolved, { recursive: true, force: true });
  }
});

it('reports live command progress before a Classic CLI check finishes', async () => {
  const base = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-cli-handoffs-'));
  roots.push(base);
  const root = path.join(base, 'project'),
    home = path.join(base, 'home');
  await fs.mkdir(home);
  await prepareClassicLegacyProject(root);
  await fs.appendFile(path.join(root, '.comet/config.yaml'), '  document_evidence: strict\n');
  const env = {
    ...process.env,
    HOME: home,
    USERPROFILE: home,
    APPDATA: path.join(home, 'AppData/Roaming'),
    LOCALAPPDATA: path.join(home, 'AppData/Local'),
    XDG_DATA_HOME: path.join(home, '.local/share'),
    XDG_CONFIG_HOME: path.join(home, '.config'),
    XDG_CACHE_HOME: path.join(home, '.cache'),
    GIT_CONFIG_GLOBAL: path.join(home, '.gitconfig'),
    GIT_CONFIG_SYSTEM: path.join(home, 'git-system'),
    COMET_DAEMON: 'off',
    COMET_SKIP_UPDATE_CHECK: '1',
    NODE_OPTIONS: '',
    COMET_TASK: '',
    COMET_TASK_PHASE: '',
    COMET_TASK_PATH: '',
  };
  const runProcess = (program: string, args: string[], input?: string) =>
    spawnSync(program, args, {
      cwd: root,
      env,
      encoding: 'utf8',
      input,
      timeout: 90_000,
      windowsHide: true,
    });
  expect(runProcess('git', ['init', '-b', 'main']).status).toBe(0);
  expect(
    runProcess('git', [
      '-c',
      'user.name=Test',
      '-c',
      'user.email=test@example.invalid',
      'commit',
      '--allow-empty',
      '-m',
      'fixture',
    ]).status,
  ).toBe(0);
  const node = globalThis.process.execPath;
  const cli = (...args: string[]) =>
    runProcess(node, [path.join(repository, 'bin/comet.js'), ...args]);
  const checked = (...args: string[]) => {
    const result = cli(...args);
    expect(result.status, result.stderr || result.stdout).toBe(0);
    return { result, body: JSON.parse(result.stdout) };
  };
  checked(
    'state',
    'init',
    'demo',
    'tweak',
    '--isolation',
    'current',
    '--runtime',
    'compat',
    '--json',
  );
  checked('state', 'select', 'demo', '--json');
  const change = path.join(root, 'openspec/changes/demo');
  for (const [name, source] of Object.entries({
    'proposal.md': '# Proposal\nPreserve the worker.\n',
    'design.md': '# Design\nKeep output one.\n',
    'tasks.md': '- [x] Keep worker behavior\n',
  }))
    await fs.writeFile(path.join(change, name), source);
  await fs.writeFile(path.join(root, 'worker.py'), 'value = 1\n');
  checked('guard', 'demo', 'open', '--apply', '--json');
  const marker = path.join(base, 'executions');
  const argv = [
    node,
    '-e',
    "setTimeout(()=>require('node:fs').appendFileSync(process.argv[1],'checked\\n'),8000)",
    marker,
  ];
  await fs.writeFile(
    path.join(root, '.comet/check-policy.json'),
    JSON.stringify({ version: 2, commands: [{ argv, cwd: '.', files: ['worker.py'] }] }),
  );
  const live = await new Promise<{
    status: number | null;
    stdout: string;
    stderr: string;
    progressBeforeFinish: boolean;
  }>((resolve, reject) => {
    const child = spawn(
      node,
      [
        path.join(repository, 'bin/comet.js'),
        'check',
        'run',
        'demo',
        'build',
        '--json',
        '--',
        ...argv,
      ],
      { cwd: root, env, timeout: 90_000, windowsHide: true },
    );
    let stdout = '',
      stderr = '',
      progressBeforeFinish = false;
    child.stdout.on('data', (chunk) => {
      stdout += String(chunk);
    });
    child.stderr.on('data', (chunk) => {
      stderr += String(chunk);
      if (stderr.includes('[Comet]') && !existsSync(marker)) progressBeforeFinish = true;
    });
    child.on('error', reject);
    child.on('close', (status) => resolve({ status, stdout, stderr, progressBeforeFinish }));
  });
  expect(live.status, live.stderr || live.stdout).toBe(0);
  expect(live.progressBeforeFinish).toBe(true);
  const build = { body: JSON.parse(live.stdout), result: live };
  expect(build.body.data.exitCode).toBe(0);
  expect(await fs.readFile(marker, 'utf8')).toBe('checked\n');
  expect(build.result.stderr).toContain('[Comet]');
});
